    public function __construct(){ $this->tenant=new TenantContext();$this->operationalAccess=new InventoryOperationalAccessService(); }

    public function assertOrderAccess(int $orderId,int $actor): void
    {
        $statement=\db()->prepare('SELECT warehouse_id,destination_location_id FROM purchase_orders WHERE company_id=:company AND purchase_order_id=:id');
        $statement->execute(['company'=>$this->tenant->companyId(),'id'=>$orderId]);
        $order=$statement->fetch(PDO::FETCH_ASSOC);
        if(!is_array($order)||!$this->canAccessOrder($order,$actor))throw new RuntimeException('Purchase Order was not found.');
    }

    public function orderAccessible(int $orderId,int $actor): bool
    {
        try{$this->assertOrderAccess($orderId,$actor);return true;}catch(RuntimeException){return false;}
    }

    /** @param array<string,mixed> $order */
    private function canAccessOrder(array $order,int $actor): bool
    {
        return $this->operationalAccess->canAccessRecord($this->tenant->companyId(),$actor,$order,'warehouse_id','destination_location_id');
    }

    /** @return array<string,mixed> */
    public function workspace(?int $orderId=null): array
    {
        $c=\db();$company=$this->tenant->companyId();
        $q=fn(string $sql,array $p=[])=>function()use($c,$sql,$p){$s=$c->prepare($sql);$s->execute($p);return $s->fetchAll(PDO::FETCH_ASSOC);};
        $base=['company_id'=>$company];$actor=(int)($_SESSION['auth']['user_id']??0);
        $data=['suppliers'=>$q("SELECT * FROM purchase_suppliers WHERE company_id=:company_id ORDER BY business_name LIMIT 100",$base)(),
            'requisitions'=>$q("SELECT r.*,u.display_name requester_name FROM purchase_requisitions r JOIN users u ON u.user_id=r.requester_user_id WHERE r.company_id=:company_id ORDER BY r.requisition_id DESC LIMIT 100",$base)(),
            'orders'=>$q("SELECT o.*,s.business_name supplier_name,w.name warehouse_name,d.name destination_location_name,COALESCE(SUM(l.received_quantity),0) received_quantity,COALESCE(SUM(l.billed_quantity),0) billed_quantity FROM purchase_orders o JOIN purchase_suppliers s ON s.company_id=o.company_id AND s.supplier_id=o.supplier_id LEFT JOIN inventory_warehouses w ON w.company_id=o.company_id AND w.warehouse_id=o.warehouse_id LEFT JOIN inventory_warehouse_locations d ON d.company_id=o.company_id AND d.warehouse_id=o.warehouse_id AND d.location_id=o.destination_location_id LEFT JOIN purchase_order_lines l ON l.company_id=o.company_id AND l.purchase_order_id=o.purchase_order_id WHERE o.company_id=:company_id GROUP BY o.purchase_order_id ORDER BY o.purchase_order_id DESC LIMIT 100",$base)(),
            'products'=>$q("SELECT product_id,sku,name,unit_of_measure,product_type FROM sales_products WHERE company_id=:company_id AND active=TRUE AND deleted_at IS NULL ORDER BY name",$base)(),
            'warehouses'=>$this->operationalAccess->warehousesForUser($company,$actor),
            'receiving_locations'=>$this->operationalAccess->receivingLocationsForUser($company,$actor),
            'bills'=>$q("SELECT i.*,s.business_name supplier_name,o.po_number FROM finance_invoices i JOIN purchase_suppliers s ON s.company_id=i.company_id AND s.supplier_id=i.vendor_id JOIN purchase_orders o ON o.company_id=i.company_id AND o.purchase_order_id=i.purchase_order_id WHERE i.company_id=:company_id AND i.document_type='vendor_bill' ORDER BY i.invoice_id DESC LIMIT 100",$base)(),
            'payment_journals'=>$q("SELECT journal_id,journal_name,journal_type FROM finance_journals WHERE company_id=:company_id AND journal_type IN('bank','cash') AND active=TRUE ORDER BY journal_type,journal_name",$base)(),
