    public function createSupplier(array $in,int $actor): int
    { $code=strtoupper(trim((string)($in['supplier_code']??'')));$name=trim((string)($in['business_name']??''));$currency=strtoupper(trim((string)($in['currency']??'ETB')));if($code===''||$name===''||!preg_match('/^[A-Z]{3}$/',$currency))throw new RuntimeException('Supplier code, business name and a valid currency are required.');$s=\db()->prepare("INSERT INTO purchase_suppliers(company_id,supplier_code,business_name,contact_person,phone,email,address,tax_number,payment_terms_days,currency,created_by,updated_by) VALUES(:company,:code,:name,:contact,:phone,:email,:address,:tax,:terms,:currency,:created_by,:updated_by)");$s->execute(['company'=>$this->tenant->companyId(),'code'=>$code,'name'=>$name,'contact'=>$this->text($in['contact_person']??null),'phone'=>$this->text($in['phone']??null),'email'=>$this->text($in['email']??null),'address'=>$this->text($in['address']??null),'tax'=>$this->text($in['tax_number']??null),'terms'=>max(0,(int)($in['payment_terms_days']??0)),'currency'=>$currency,'created_by'=>$actor,'updated_by'=>$actor]);$id=(int)\db()->lastInsertId();$this->audit($actor,'supplier.created','purchase_suppliers',$id,['supplier_code'=>$code]);return$id; }

    public function createRequisition(array $in,int $actor): int
    { $lines=$this->lines($in,false);$just=trim((string)($in['justification']??''));$department=(int)($in['department_id']??0);$warehouse=(int)($in['warehouse_id']??0);if($just===''||$lines===[]||$department<1||$warehouse<1)throw new RuntimeException('Department, warehouse, justification and at least one valid line are required.');$c=\db();$c->beginTransaction();try{$company=$this->tenant->companyId();$this->assertDepartment($c,$company,$department);$this->assertWarehouse($c,$company,$warehouse);$this->assertProducts($c,$company,$lines);$number='PR-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$s=$c->prepare("INSERT INTO purchase_requisitions(company_id,requisition_number,requester_user_id,department_id,requested_date,required_by_date,justification,status) VALUES(:company,:number,:actor,:department,CURRENT_DATE,:required,:justification,'draft')");$s->execute(['company'=>$company,'number'=>$number,'actor'=>$actor,'department'=>$department,'required'=>$this->date($in['required_by_date']??null),'justification'=>$just]);$id=(int)$c->lastInsertId();$add=$c->prepare("INSERT INTO purchase_requisition_lines(company_id,requisition_id,product_id,description,quantity,estimated_unit_price,preferred_supplier_id,warehouse_id) VALUES(:company,:id,:product,:description,:quantity,:price,:supplier,:warehouse)");foreach($lines as $l)$add->execute(['company'=>$company,'id'=>$id,'product'=>$l['product_id'],'description'=>$l['description'],'quantity'=>$l['quantity'],'price'=>$l['unit_price'],'supplier'=>null,'warehouse'=>$warehouse]);$c->commit();$this->audit($actor,'requisition.created','purchase_requisitions',$id,['number'=>$number]);return$id;}catch(Throwable $e){if($c->inTransaction())$c->rollBack();throw$e;} }

    public function transitionRequisition(int $id,string $action,int $actor,?string $reason=null): void
    { $map=['submit'=>['draft','submitted'],'approve'=>['submitted','approved'],'reject'=>['submitted','rejected'],'cancel'=>['draft','cancelled']];if(!isset($map[$action]))throw new RuntimeException('Invalid requisition action.');[$from,$to]=$map[$action];if($action==='reject'&&trim((string)$reason)==='')throw new RuntimeException('A rejection reason is required.');$s=\db()->prepare("UPDATE purchase_requisitions SET status=:new_status,rejection_reason=:reason,approved_by=IF(:approval_status='approved',:approval_actor,approved_by),approved_at=IF(:approval_time_status='approved',NOW(),approved_at) WHERE company_id=:company AND requisition_id=:id AND status=:old_status AND (:separation_status<>'approved' OR requester_user_id<>:separation_actor)");$s->execute(['new_status'=>$to,'approval_status'=>$to,'approval_time_status'=>$to,'separation_status'=>$to,'reason'=>$this->text($reason),'approval_actor'=>$actor,'separation_actor'=>$actor,'company'=>$this->tenant->companyId(),'id'=>$id,'old_status'=>$from]);if($s->rowCount()!==1)throw new RuntimeException('The requisition transition is invalid, stale, or violates separation of duties.');$this->audit($actor,'requisition.'.$action,'purchase_requisitions',$id,['status'=>$to]); }

    public function createOrder(array $in,int $actor): int
    { $company=$this->tenant->companyId();$supplier=(int)($in['supplier_id']??0);$warehouse=(int)($in['warehouse_id']??0);$destination=(int)($in['destination_location_id']??0);$req=(int)($in['requisition_id']??0)?:null;$c=\db();$c->beginTransaction();try{$s=$c->prepare("SELECT * FROM purchase_suppliers WHERE company_id=:company AND supplier_id=:id AND active=TRUE FOR UPDATE");$s->execute(['company'=>$company,'id'=>$supplier]);$vendor=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($vendor))throw new RuntimeException('Select an active supplier in this company.');if($req){$r=$c->prepare("SELECT status FROM purchase_requisitions WHERE company_id=:company AND requisition_id=:id FOR UPDATE");$r->execute(['company'=>$company,'id'=>$req]);if($r->fetchColumn()!=='approved')throw new RuntimeException('Only an approved requisition can be converted.');$l=$c->prepare("SELECT product_id,description,quantity,estimated_unit_price unit_price FROM purchase_requisition_lines WHERE company_id=:company AND requisition_id=:id");$l->execute(['company'=>$company,'id'=>$req]);$lines=$l->fetchAll(PDO::FETCH_ASSOC);}else{$lines=$this->lines($in,true);}if($lines===[])throw new RuntimeException('At least one valid line is required.');$stocked=$this->containsStockedProducts($c,$company,$lines);if($stocked){if($warehouse<1||$destination<1)throw new RuntimeException('Destination warehouse and receiving location are required for inventory-stocked products.');$this->operationalAccess->assertAuthorizedDestination($company,$actor,$warehouse,$destination);}else{$warehouse=$destination=0;}[$calc,$subtotal,$tax,$total]=$this->calculate($lines);$number='PO-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));$h=$c->prepare("INSERT INTO purchase_orders(company_id,po_number,supplier_id,requisition_id,warehouse_id,destination_location_id,order_date,expected_date,currency,payment_terms_days,supplier_reference,notes,subtotal,tax_amount,total_amount,status,created_by) VALUES(:company,:number,:supplier,:req,:warehouse,:destination,CURRENT_DATE,:expected,:currency,:terms,:reference,:notes,:subtotal,:tax,:total,'draft',:actor)");$h->execute(['company'=>$company,'number'=>$number,'supplier'=>$supplier,'req'=>$req,'warehouse'=>$warehouse?:null,'destination'=>$destination?:null,'expected'=>$this->date($in['expected_date']??null),'currency'=>$vendor['currency'],'terms'=>$vendor['payment_terms_days'],'reference'=>$this->text($in['supplier_reference']??null),'notes'=>$this->text($in['notes']??null),'subtotal'=>$subtotal,'tax'=>$tax,'total'=>$total,'actor'=>$actor]);$id=(int)$c->lastInsertId();$add=$c->prepare("INSERT INTO purchase_order_lines(company_id,purchase_order_id,product_id,description,ordered_quantity,unit_price,discount_amount,tax_rate,untaxed_amount,tax_amount,line_total) VALUES(:company,:id,:product,:description,:quantity,:price,0,:tax_rate,:untaxed,:tax,:total)");foreach($calc as $l)$add->execute(['company'=>$company,'id'=>$id,'product'=>$l['product_id'],'description'=>$l['description'],'quantity'=>$l['quantity'],'price'=>$l['unit_price'],'tax_rate'=>$l['tax_rate'],'untaxed'=>$l['untaxed'],'tax'=>$l['tax'],'total'=>$l['total']]);if($req)$c->prepare("UPDATE purchase_requisitions SET status='converted' WHERE company_id=:company AND requisition_id=:id AND status='approved'")->execute(['company'=>$company,'id'=>$req]);$c->commit();$this->audit($actor,'order.created','purchase_orders',$id,['number'=>$number,'total'=>$total,'warehouse_id'=>$warehouse?:null,'destination_location_id'=>$destination?:null]);return$id;}catch(Throwable $e){if($c->inTransaction())$c->rollBack();throw$e;} }

    public function transitionOrder(int $id,string $action,int $actor): void
    { $map=['submit'=>['draft','submitted'],'approve'=>['submitted','approved'],'confirm'=>['approved','confirmed'],'cancel'=>['draft','cancelled'],'close'=>['billed','closed']];if(!isset($map[$action]))throw new RuntimeException('Invalid purchase order action.');[$from,$to]=$map[$action];$company=$this->tenant->companyId();$c=\db();$owns=!$c->inTransaction();try{if($owns)$c->beginTransaction();if($action==='approve'){$row=$c->prepare('SELECT created_by,total_amount FROM purchase_orders WHERE company_id=:company AND purchase_order_id=:id AND status=:status FOR UPDATE');$row->execute(['company'=>$company,'id'=>$id,'status'=>$from]);$order=$row->fetch(PDO::FETCH_ASSOC);if(!$order)throw new RuntimeException('The purchase order transition is no longer valid.');(new ApprovalPolicyService())->assertAndRecord($company,'purchase_order.approve','purchase_order',$id,(float)$order['total_amount'],(int)$order['created_by'],$actor);}$extra=$action==='approve'?',approved_by=:actor,approved_at=NOW()':($action==='confirm'?',confirmed_by=:actor,confirmed_at=NOW()':($action==='close'?',closed_by=:actor,closed_at=NOW()':''));$s=$c->prepare("UPDATE purchase_orders SET status=:to$extra WHERE company_id=:company AND purchase_order_id=:id AND status=:from");$parameters=['to'=>$to,'company'=>$company,'id'=>$id,'from'=>$from];if($extra!=='')$parameters['actor']=$actor;$s->execute($parameters);if($s->rowCount()!==1)throw new RuntimeException('The purchase order transition is no longer valid.');$this->audit($actor,'order.'.$action,'purchase_orders',$id,['status'=>$to]);if($owns)$c->commit();}catch(Throwable $e){if($owns&&$c->inTransaction())$c->rollBack();throw$e;} }

    public function createReceipt(int $orderId,array $quantities,int $actor): int
    { $company=$this->tenant->companyId();$c=\db();$c->beginTransaction();try{$s=$c->prepare("SELECT o.*,v.business_name FROM purchase_orders o JOIN purchase_suppliers v ON v.company_id=o.company_id AND v.supplier_id=o.supplier_id WHERE o.company_id=:company AND o.purchase_order_id=:id AND o.status IN('confirmed','partially_received') FOR UPDATE");$s->execute(['company'=>$company,'id'=>$orderId]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($o))throw new RuntimeException('Only a confirmed purchase order can be received.');if(empty($o['warehouse_id'])||empty($o['destination_location_id']))throw new RuntimeException('This Purchase Order has no explicit receiving destination; no fallback is permitted.');$this->operationalAccess->assertAuthorizedDestination($company,$actor,(int)$o['warehouse_id'],(int)$o['destination_location_id']);$ls=$c->prepare("SELECT l.*,p.product_type FROM purchase_order_lines l INNER JOIN sales_products p ON p.company_id=l.company_id AND p.product_id=l.product_id WHERE l.company_id=:company AND l.purchase_order_id=:id FOR UPDATE");$ls->execute(['company'=>$company,'id'=>$orderId]);$lines=[];foreach($ls->fetchAll(PDO::FETCH_ASSOC) as $l){$qty=round((float)($quantities[(int)$l['purchase_order_line_id']]??0),3);if(in_array((string)$l['product_type'],['service','fixed_asset'],true)){if($qty>0)throw new RuntimeException('Fixed-asset and non-stock acquisitions cannot be posted into warehouse stock.');continue;}$remaining=round((float)$l['ordered_quantity']-(float)$l['received_quantity'],3);if($qty<0||$qty>$remaining)throw new RuntimeException('Receipt quantity exceeds the outstanding quantity.');if($qty>0)$lines[]=['product_id'=>(int)$l['product_id'],'purchase_order_line_id'=>(int)$l['purchase_order_line_id'],'quantity'=>$qty,'unit_cost'=>$l['unit_price'],'notes'=>'Purchase order '.$o['po_number']];}if($lines===[])throw new RuntimeException('Enter at least one positive inventory receipt quantity.');$id=RepositoryFactory::inventory()->createGoodsReceipt($company,['warehouse_id'=>(int)$o['warehouse_id'],'destination_location_id'=>(int)$o['destination_location_id'],'supplier_name'=>$o['business_name'],'supplier_reference'=>$o['supplier_reference'],'purchase_order_id'=>$orderId,'receipt_date'=>date('Y-m-d'),'currency'=>$o['currency'],'notes'=>'Created from '.$o['po_number']],$lines,$actor);$c->commit();$this->audit($actor,'receipt.linked','inventory_goods_receipts',$id,['purchase_order_id'=>$orderId,'warehouse_id'=>(int)$o['warehouse_id'],'destination_location_id'=>(int)$o['destination_location_id']]);return$id;}catch(Throwable $e){if($c->inTransaction())$c->rollBack();throw$e;} }

    public function createBill(int $orderId,string $supplierNumber,int $actor): int
    {
        $company=$this->tenant->companyId();$c=\db();$c->beginTransaction();
        try{
            $supplierNumber=trim($supplierNumber);if($supplierNumber==='')throw new RuntimeException('Supplier invoice number is required.');
            $s=$c->prepare("SELECT * FROM purchase_orders WHERE company_id=:company AND purchase_order_id=:id AND status IN('partially_received','received','partially_billed') FOR UPDATE");$s->execute(['company'=>$company,'id'=>$orderId]);$o=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($o))throw new RuntimeException('The purchase order has no received quantity available to bill.');
            $ls=$c->prepare("SELECT * FROM purchase_order_lines WHERE company_id=:company AND purchase_order_id=:id FOR UPDATE");$ls->execute(['company'=>$company,'id'=>$orderId]);$lines=[];$subtotal=$tax=$total=0.0;
            foreach($ls->fetchAll(PDO::FETCH_ASSOC) as $l){$qty=round((float)$l['received_quantity']-(float)$l['returned_quantity']-(float)$l['billed_quantity'],3);if($qty<=0)continue;$untaxed=round($qty*(float)$l['unit_price'],2);$lineTax=round($untaxed*(float)$l['tax_rate']/100,2);$lines[]=[$l,$qty,$untaxed,$lineTax];$subtotal+=$untaxed;$tax+=$lineTax;$total+=$untaxed+$lineTax;}
            if($lines===[])throw new RuntimeException('There is no legitimately received net quantity left to bill.');
            $journals=RepositoryFactory::finance()->ensureSystemJournals($company,(string)$o['currency'],$actor);$n='BILL-'.date('Ymd').'-'.strtoupper(substr(bin2hex(random_bytes(3)),0,6));
            $h=$c->prepare("INSERT INTO finance_invoices(company_id,journal_id,vendor_id,purchase_order_id,document_type,invoice_number,supplier_invoice_number,invoice_date,due_date,currency,payment_terms_days,invoice_policy,status,payment_status,untaxed_amount,tax_amount,total_amount,residual_amount,created_by) VALUES(:company,:journal,:vendor,:po,'vendor_bill',:number,:supplier_number,CURRENT_DATE,DATE_ADD(CURRENT_DATE,INTERVAL :due_terms DAY),:currency,:payment_terms,'delivered','draft','unpaid',:subtotal,:tax,:invoice_total,:residual_total,:actor)");
            $h->execute(['company'=>$company,'journal'=>$journals['purchase'],'vendor'=>$o['supplier_id'],'po'=>$orderId,'number'=>$n,'supplier_number'=>$supplierNumber,'due_terms'=>$o['payment_terms_days'],'payment_terms'=>$o['payment_terms_days'],'currency'=>$o['currency'],'subtotal'=>round($subtotal,2),'tax'=>round($tax,2),'invoice_total'=>round($total,2),'residual_total'=>round($total,2),'actor'=>$actor]);
