            $status=$c->prepare("UPDATE purchase_orders SET status=CASE WHEN NOT EXISTS(SELECT 1 FROM purchase_order_lines l WHERE l.company_id=:line_company AND l.purchase_order_id=:line_order AND l.billed_quantity<l.received_quantity-l.returned_quantity) THEN 'billed' ELSE 'partially_billed' END WHERE company_id=:order_company AND purchase_order_id=:order_id");$status->execute(['line_company'=>$company,'line_order'=>$orderId,'order_company'=>$company,'order_id'=>$orderId]);
            $this->event($company,'SupplierBillCreated','purchase_order',(string)$orderId,['invoice_id'=>$id]);$c->commit();$this->audit($actor,'bill.created','finance_invoices',$id,['purchase_order_id'=>$orderId]);return$id;
        }catch(Throwable $e){if($c->inTransaction())$c->rollBack();throw$e;}
    }

    public function postBill(int $invoiceId,int $actor): array
