            $lines=$c->prepare("SELECT purchase_order_line_id,quantity FROM finance_invoice_lines WHERE company_id=:company AND invoice_id=:id AND purchase_order_line_id IS NOT NULL FOR UPDATE");$lines->execute(['company'=>$company,'id'=>$invoiceId]);
            foreach($lines->fetchAll(PDO::FETCH_ASSOC) as $line){$u=$c->prepare("UPDATE purchase_order_lines SET billed_quantity=billed_quantity-:quantity WHERE company_id=:company AND purchase_order_line_id=:line AND billed_quantity>=:required_quantity");$u->execute(['quantity'=>$line['quantity'],'required_quantity'=>$line['quantity'],'company'=>$company,'line'=>$line['purchase_order_line_id']]);if($u->rowCount()!==1)throw new RuntimeException('Supplier bill quantities could not be reconciled safely.');}
