        }catch(Throwable $e){if($c->inTransaction())$c->rollBack();throw$e;}
    }

    private function lines(array $in,bool $priced): array
    {
        $out=[];
        foreach((array)($in['product_id']??[]) as $i=>$p){
            $id=(int)$p;$rawQty=((array)($in['quantity']??[]))[$i]??null;$rawPrice=((array)($in['unit_price']??[]))[$i]??0;$rawTax=((array)($in['tax_rate']??[]))[$i]??0;
            if(!is_numeric($rawQty)||($priced&&!is_numeric($rawPrice))||!is_numeric($rawTax))throw new RuntimeException('Item quantities, prices and tax rates must be numeric.');
            $qty=round((float)$rawQty,3);$price=round((float)$rawPrice,4);$tax=round((float)$rawTax,4);
            if($id<1||$qty<=0||$price<0||$tax<0||$tax>100)throw new RuntimeException('Each item requires a company product, positive quantity, non-negative price and tax from 0 to 100.');
            $out[]=['product_id'=>$id,'description'=>trim((string)(((array)($in['description']??[]))[$i]??'Purchased item'))?:'Purchased item','quantity'=>$qty,'unit_price'=>$price,'tax_rate'=>$tax];
        }
        return$out;
    }
    private function assertDepartment(PDO $c,int $company,int $id): void { $s=$c->prepare('SELECT 1 FROM hr_departments WHERE company_id=:company AND department_id=:id AND active=TRUE AND deleted_at IS NULL');$s->execute(['company'=>$company,'id'=>$id]);if(!$s->fetchColumn())throw new RuntimeException('Select an active department in this company.'); }
    private function assertWarehouse(PDO $c,int $company,int $id): void { $s=$c->prepare('SELECT 1 FROM inventory_warehouses WHERE company_id=:company AND warehouse_id=:id AND active=TRUE AND deleted_at IS NULL');$s->execute(['company'=>$company,'id'=>$id]);if(!$s->fetchColumn())throw new RuntimeException('Select an active warehouse in this company.'); }
    private function assertProducts(PDO $c,int $company,array $lines): void { $s=$c->prepare('SELECT 1 FROM sales_products WHERE company_id=:company AND product_id=:id AND active=TRUE AND deleted_at IS NULL');foreach($lines as $line){$s->execute(['company'=>$company,'id'=>$line['product_id']]);if(!$s->fetchColumn())throw new RuntimeException('Every item must be an active product in this company.');} }
    private function containsStockedProducts(PDO $c,int $company,array $lines): bool { $s=$c->prepare("SELECT product_type FROM sales_products WHERE company_id=:company AND product_id=:id AND active=TRUE AND deleted_at IS NULL");$stocked=false;foreach($lines as $line){$s->execute(['company'=>$company,'id'=>$line['product_id']]);$type=$s->fetchColumn();if($type===false)throw new RuntimeException('Every item must be an active product in this company.');if(!in_array((string)$type,['service','fixed_asset'],true))$stocked=true;}return $stocked; }
    private function calculate(array $lines): array { $this->assertProducts(\db(),$this->tenant->companyId(),$lines);$out=[];$sub=$tax=$total=0.0;foreach($lines as $l){$u=round((float)$l['quantity']*(float)$l['unit_price'],2);$t=round($u*(float)($l['tax_rate']??0)/100,2);$l+=['tax_rate'=>0];$l['untaxed']=$u;$l['tax']=$t;$l['total']=$u+$t;$out[]=$l;$sub+=$u;$tax+=$t;$total+=$u+$t;}return[$out,round($sub,2),round($tax,2),round($total,2)]; }
    private function audit(int $actor,string $action,string $table,int $id,?array $values): void { RepositoryFactory::auditLogs()->record($actor,$action,'procurement',$table,(string)$id,null,$values,$this->tenant->companyId()); }
    private function text(mixed $v): ?string { $v=trim((string)$v);return $v===''?null:$v; }
    private function date(mixed $v): ?string { $v=trim((string)$v);return preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)?$v:null; }
    private function event(int $company,string $type,string $aggregate,string $id,array $payload): void { $s=\db()->prepare("INSERT INTO integration_outbox(event_id,company_id,event_type,aggregate_type,aggregate_id,payload_json,status,available_at) VALUES(:event,:company,:type,:aggregate,:id,:payload,'pending',NOW())");$s->execute(['event'=>$this->uuid(),'company'=>$company,'type'=>$type,'aggregate'=>$aggregate,'id'=>$id,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR)]); }
    private function uuid(): string { $b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4)); }
